import { useState, type MouseEvent, type ReactNode } from "react";
import { Bell, FolderKanban, LayoutDashboard, Menu as MenuIcon, Settings, Users } from "lucide-react";
import {
  Avatar,
  GlobalNav,
  IconButton,
  NavItem,
  NavPanel,
  NavSection,
  SearchInput,
  Sheet,
  SheetBody,
  SheetHeader,
  SheetTitle,
} from "@nucleux/react";

export interface ShellLink {
  id: string;
  label: string;
  href: string;
  icon: ReactNode;
}

export const SHELL_LINKS: ShellLink[] = [
  { id: "dashboard", label: "Dashboard", href: "/", icon: <LayoutDashboard className="size-4" /> },
  { id: "projects", label: "Projects", href: "/projects", icon: <FolderKanban className="size-4" /> },
  { id: "team", label: "Team", href: "/team", icon: <Users className="size-4" /> },
  { id: "settings", label: "Settings", href: "/settings", icon: <Settings className="size-4" /> },
];

export interface AppShellProps {
  /** id of the active link. */
  current: string;
  /** Called with the link's href; wire it to your router (e.g. `navigate(href)`). */
  onNavigate: (href: string) => void;
  links?: ShellLink[];
  children: ReactNode;
}

/** One nav list, rendered both in the desktop column and in the mobile sheet. */
function ShellNav({
  links,
  current,
  onSelect,
}: {
  links: ShellLink[];
  current: string;
  onSelect: (href: string) => void;
}) {
  return (
    <NavSection title="Workspace">
      {links.map((link) => (
        <NavItem
          key={link.id}
          href={link.href}
          active={link.id === current}
          className="h-9 gap-2 text-sm"
          onClick={(e: MouseEvent<HTMLAnchorElement>) => {
            e.preventDefault();
            onSelect(link.href);
          }}
        >
          {link.icon}
          {link.label}
        </NavItem>
      ))}
    </NavSection>
  );
}

/**
 * Application shell: persistent left navigation on large screens, a top bar
 * with search and account, and a slide-in navigation sheet on small screens.
 * Page content renders inside `<main>`.
 */
export function AppShell({ current, onNavigate, links = SHELL_LINKS, children }: AppShellProps) {
  const [mobileOpen, setMobileOpen] = useState(false);
  const go = (href: string) => {
    setMobileOpen(false);
    onNavigate(href);
  };

  return (
    <div className="flex h-screen bg-background text-foreground">
      <NavPanel aria-label="Primary" className="hidden lg:flex">
        <div className="px-4 text-sm font-semibold text-foreground">Acme Projects</div>
        <ShellNav links={links} current={current} onSelect={go} />
      </NavPanel>

      <div className="flex min-w-0 flex-1 flex-col">
        <GlobalNav
          className="px-4 sm:px-6"
          left={
            <>
              <IconButton aria-label="Open navigation" className="lg:hidden" onClick={() => setMobileOpen(true)}>
                <MenuIcon className="size-5" />
              </IconButton>
              <span className="truncate text-sm font-semibold lg:hidden">Acme Projects</span>
            </>
          }
          center={
            <SearchInput
              aria-label="Search projects and tasks"
              placeholder="Search projects and tasks"
              containerClassName="hidden w-full max-w-md sm:flex"
            />
          }
          right={
            <>
              <IconButton aria-label="Notifications">
                <Bell className="size-5" />
              </IconButton>
              <Avatar role="user" name="Dana Kim" initials="DK" />
            </>
          }
        />
        <main className="min-h-0 flex-1 overflow-y-auto">{children}</main>
      </div>

      <Sheet open={mobileOpen} onOpenChange={setMobileOpen} side="left">
        <SheetHeader>
          <SheetTitle>Acme Projects</SheetTitle>
        </SheetHeader>
        <SheetBody className="px-0">
          <nav aria-label="Primary">
            <ShellNav links={links} current={current} onSelect={go} />
          </nav>
        </SheetBody>
      </Sheet>
    </div>
  );
}

export default function AppShellExample() {
  const [current, setCurrent] = useState("dashboard");
  return (
    <AppShell
      current={current}
      onNavigate={(href) => setCurrent(SHELL_LINKS.find((l) => l.href === href)?.id ?? "dashboard")}
    >
      <div className="mx-auto max-w-6xl p-4 sm:p-6 lg:p-8">
        <p className="text-sm text-muted-foreground">Page content renders here.</p>
      </div>
    </AppShell>
  );
}

import type { ReactNode } from "react";
import { CheckCircle2, Clock, FolderKanban, TrendingUp } from "lucide-react";
import {
  Badge,
  CardContainer,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
  PageHeader,
  Progress,
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@nucleux/react";

export interface Metric {
  label: string;
  value: string;
  change: string;
  icon: ReactNode;
}

/** A single KPI tile. Keep the value short; put context in `change`. */
export function MetricCard({ label, value, change, icon }: Metric) {
  return (
    <CardContainer>
      <CardContent className="flex items-start justify-between gap-4">
        <div className="min-w-0">
          <p className="text-sm text-muted-foreground">{label}</p>
          <p className="mt-1 text-2xl font-semibold tabular-nums text-foreground">{value}</p>
          <p className="mt-1 text-xs text-muted-foreground">{change}</p>
        </div>
        <span aria-hidden className="text-muted-foreground [&_svg]:size-5">
          {icon}
        </span>
      </CardContent>
    </CardContainer>
  );
}

const METRICS: Metric[] = [
  { label: "Active projects", value: "12", change: "+2 this month", icon: <FolderKanban /> },
  { label: "Tasks completed", value: "248", change: "+18% vs last month", icon: <CheckCircle2 /> },
  { label: "Overdue tasks", value: "7", change: "3 due today", icon: <Clock /> },
  { label: "On-time delivery", value: "92%", change: "Up from 88%", icon: <TrendingUp /> },
];

const PROGRESS = [
  { name: "Website redesign", done: 72 },
  { name: "Mobile onboarding", done: 38 },
  { name: "Billing migration", done: 55 },
];

const ACTIVITY = [
  { who: "Dana Kim", what: "completed “Homepage hero”", when: "10 min ago", tag: "Done" },
  { who: "Luis Ortega", what: "flagged “Push permissions” as blocked", when: "1 h ago", tag: "Blocked" },
  { who: "Priya Shah", what: "opened “Invoice export”", when: "3 h ago", tag: "New" },
];

/**
 * Overview dashboard: a responsive KPI row, a progress panel and a recent
 * activity table. Each region is a card so it can be rearranged or removed.
 */
export default function DashboardOverviewExample() {
  return (
    <div className="mx-auto flex max-w-6xl flex-col gap-6 p-4 sm:p-6 lg:p-8">
      <PageHeader title="Dashboard" description="Where your projects stand this week." />

      <section aria-label="Key metrics" className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4">
        {METRICS.map((m) => (
          <MetricCard key={m.label} {...m} />
        ))}
      </section>

      <div className="grid gap-4 lg:grid-cols-3">
        <CardContainer className="lg:col-span-1">
          <CardHeader>
            <CardTitle aria-level={2}>Project progress</CardTitle>
            <CardDescription>Share of tasks completed</CardDescription>
          </CardHeader>
          <CardContent className="space-y-4">
            {PROGRESS.map((p) => (
              <div key={p.name} className="space-y-1.5">
                <div className="flex justify-between text-sm">
                  <span className="text-foreground">{p.name}</span>
                  <span className="tabular-nums text-muted-foreground">{p.done}%</span>
                </div>
                <Progress value={p.done} size="sm" aria-label={`${p.name} progress`} />
              </div>
            ))}
          </CardContent>
        </CardContainer>

        <CardContainer className="lg:col-span-2">
          <CardHeader>
            <CardTitle aria-level={2}>Recent activity</CardTitle>
          </CardHeader>
          <CardContent className="overflow-x-auto">
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead>Member</TableHead>
                  <TableHead>Activity</TableHead>
                  <TableHead className="hidden sm:table-cell">When</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {ACTIVITY.map((a) => (
                  <TableRow key={a.what}>
                    <TableCell className="font-medium">{a.who}</TableCell>
                    <TableCell>
                      <span className="mr-2">{a.what}</span>
                      <Badge variant={a.tag === "Blocked" ? "destructive" : "secondary"}>{a.tag}</Badge>
                    </TableCell>
                    <TableCell className="hidden text-muted-foreground sm:table-cell">{a.when}</TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          </CardContent>
        </CardContainer>
      </div>
    </div>
  );
}

import { useMemo, useState } from "react";
import { Plus } from "lucide-react";
import { Badge, Button, DataTable, PageHeader, SearchInput, Select, type DataTableProps } from "@nucleux/react";

export type ProjectStatus = "active" | "at-risk" | "done";

export interface Project {
  id: string;
  name: string;
  owner: string;
  status: ProjectStatus;
  due: string;
}

const STATUS_BADGE: Record<ProjectStatus, { label: string; variant: "success" | "destructive" | "secondary" }> = {
  active: { label: "Active", variant: "success" },
  "at-risk": { label: "At risk", variant: "destructive" },
  done: { label: "Done", variant: "secondary" },
};

// Typed from DataTableProps so the page needs no direct @tanstack/react-table import.
const columns: DataTableProps<Project, unknown>["columns"] = [
  { accessorKey: "name", header: "Project" },
  { accessorKey: "owner", header: "Owner" },
  {
    accessorKey: "status",
    header: "Status",
    cell: ({ row }) => {
      const s = STATUS_BADGE[row.original.status];
      return <Badge variant={s.variant}>{s.label}</Badge>;
    },
  },
  { accessorKey: "due", header: "Due" },
];

export const SAMPLE_PROJECTS: Project[] = [
  { id: "p1", name: "Website redesign", owner: "Dana Kim", status: "active", due: "2026-11-02" },
  { id: "p2", name: "Mobile onboarding", owner: "Luis Ortega", status: "at-risk", due: "2026-10-28" },
  { id: "p3", name: "Billing migration", owner: "Priya Shah", status: "active", due: "2026-12-15" },
  { id: "p4", name: "Q3 analytics report", owner: "Sam Lee", status: "done", due: "2026-09-30" },
];

/**
 * Collection page: header with the primary action, a search + filter toolbar,
 * and a sortable, paginated table. Filtering happens before the table so the
 * table's own pagination always reflects the filtered rows.
 */
export function ProjectListPage({ projects, onCreate }: { projects: Project[]; onCreate: () => void }) {
  const [query, setQuery] = useState("");
  const [status, setStatus] = useState<"all" | ProjectStatus>("all");

  const rows = useMemo(() => {
    const q = query.trim().toLowerCase();
    return projects.filter(
      (p) =>
        (status === "all" || p.status === status) &&
        (!q || p.name.toLowerCase().includes(q) || p.owner.toLowerCase().includes(q)),
    );
  }, [projects, query, status]);

  return (
    <div className="mx-auto flex max-w-6xl flex-col gap-6 p-4 sm:p-6 lg:p-8">
      <PageHeader
        title="Projects"
        description="Track every project, its owner, and its delivery status."
        actions={
          <Button variant="cta" leftIcon={<Plus className="size-4" />} onClick={onCreate}>
            New project
          </Button>
        }
      />

      <div role="search" className="flex flex-col gap-3 sm:flex-row sm:items-center">
        <SearchInput
          aria-label="Search projects"
          placeholder="Search by project or owner"
          value={query}
          onChange={(e) => setQuery(e.target.value)}
          containerClassName="sm:max-w-sm sm:flex-1"
        />
        <Select
          aria-label="Filter by status"
          value={status}
          onChange={(e) => setStatus(e.target.value as "all" | ProjectStatus)}
          containerClassName="sm:w-44"
        >
          <option value="all">All statuses</option>
          <option value="active">Active</option>
          <option value="at-risk">At risk</option>
          <option value="done">Done</option>
        </Select>
      </div>

      <div className="overflow-x-auto">
        <DataTable columns={columns} data={rows} pageSize={10} emptyMessage="No projects match these filters." />
      </div>
    </div>
  );
}

export default function ListPageExample() {
  return <ProjectListPage projects={SAMPLE_PROJECTS} onCreate={() => undefined} />;
}

import type { ReactNode } from "react";
import { AlertTriangle, FolderOpen, RefreshCw } from "lucide-react";
import { Button, ErrorState, Skeleton } from "@nucleux/react";

export type LoadState<T> =
  | { status: "loading" }
  | { status: "error"; message: string }
  | { status: "ready"; data: T };

/** Placeholder that mirrors the shape of a list while it loads. */
export function ListSkeleton({ rows = 5 }: { rows?: number }) {
  return (
    <div role="status" aria-live="polite" className="space-y-3">
      <span className="sr-only">Loading…</span>
      {Array.from({ length: rows }, (_, i) => (
        <div key={i} className="flex items-center gap-3">
          <Skeleton circle className="size-8" />
          <div className="flex-1 space-y-2">
            <Skeleton className="h-4 w-1/3" />
            <Skeleton className="h-3 w-2/3" />
          </div>
        </div>
      ))}
    </div>
  );
}

/**
 * Renders the right state for async data: a skeleton while loading, a
 * recoverable error with Retry, an empty state with a primary action, or the
 * content itself.
 */
export function AsyncContent<T>({
  state,
  isEmpty,
  onRetry,
  empty,
  children,
}: {
  state: LoadState<T>;
  isEmpty: (data: T) => boolean;
  onRetry: () => void;
  empty: { title: string; description: string; action?: ReactNode };
  children: (data: T) => ReactNode;
}) {
  if (state.status === "loading") return <ListSkeleton />;
  if (state.status === "error") {
    return (
      <ErrorState
        role="alert"
        variant="error"
        icon={<AlertTriangle />}
        title="Couldn't load this page"
        description={state.message}
        actions={
          <Button variant="secondary" leftIcon={<RefreshCw className="size-4" />} onClick={onRetry}>
            Retry
          </Button>
        }
      />
    );
  }
  if (isEmpty(state.data)) {
    return (
      <ErrorState
        variant="empty"
        icon={<FolderOpen />}
        title={empty.title}
        description={empty.description}
        actions={empty.action}
      />
    );
  }
  return <>{children(state.data)}</>;
}

export default function PageStatesExample() {
  const retry = () => undefined;
  return (
    <div className="mx-auto grid max-w-5xl gap-6 p-6 md:grid-cols-3">
      <AsyncContent state={{ status: "loading" }} isEmpty={() => false} onRetry={retry} empty={{ title: "", description: "" }}>
        {() => null}
      </AsyncContent>
      <AsyncContent
        state={{ status: "error", message: "The server didn't respond. Your filters are kept." }}
        isEmpty={() => false}
        onRetry={retry}
        empty={{ title: "", description: "" }}
      >
        {() => null}
      </AsyncContent>
      <AsyncContent
        state={{ status: "ready", data: [] as string[] }}
        isEmpty={(d) => d.length === 0}
        onRetry={retry}
        empty={{
          title: "No projects yet",
          description: "Create a project to start tracking tasks.",
          action: <Button variant="cta">New project</Button>,
        }}
      >
        {(items) => <ul>{items.map((i) => <li key={i}>{i}</li>)}</ul>}
      </AsyncContent>
    </div>
  );
}

import { useState, type FormEvent, type ReactNode } from "react";
import {
  Alert,
  Button,
  CardContainer,
  CardContent,
  CardDescription,
  CardDivider,
  CardHeader,
  CardTitle,
  Input,
  Label,
  PageHeader,
  Select,
  Switch,
  Tabs,
  TabsContent,
  TabsList,
  TabsTrigger,
} from "@nucleux/react";

/** Label + help text on the left, the control on the right; stacks on mobile. */
export function SettingRow({ id, title, description, children }: {
  id: string;
  title: string;
  description: string;
  children: ReactNode;
}) {
  return (
    <div className="flex flex-col gap-3 py-4 sm:flex-row sm:items-center sm:justify-between">
      <div className="min-w-0">
        <p id={`${id}-label`} className="text-sm font-medium text-foreground">{title}</p>
        <p id={`${id}-desc`} className="text-sm text-muted-foreground">{description}</p>
      </div>
      {children}
    </div>
  );
}

/**
 * Settings: tabs group related sections; each section is a card of rows;
 * form sections save explicitly with a confirmation, toggles apply instantly.
 */
export default function SettingsPageExample() {
  const [name, setName] = useState("Dana Kim");
  const [saved, setSaved] = useState(false);
  const [digest, setDigest] = useState(true);

  const save = (e: FormEvent) => {
    e.preventDefault();
    setSaved(true);
  };

  return (
    <div className="mx-auto flex max-w-3xl flex-col gap-6 p-4 sm:p-6 lg:p-8">
      <PageHeader title="Settings" description="Manage your profile and notifications." />

      <Tabs defaultValue="profile">
        <TabsList>
          <TabsTrigger value="profile">Profile</TabsTrigger>
          <TabsTrigger value="notifications">Notifications</TabsTrigger>
        </TabsList>

        <TabsContent value="profile" className="pt-4">
          <CardContainer>
            <form onSubmit={save}>
              <CardHeader>
                <CardTitle aria-level={2}>Profile</CardTitle>
                <CardDescription>Shown to your teammates.</CardDescription>
              </CardHeader>
              <CardDivider />
              <CardContent className="space-y-4">
                {saved && (
                  <Alert variant="success" title="Profile saved">
                    Your changes are live.
                  </Alert>
                )}
                <div className="space-y-1.5">
                  <Label htmlFor="display-name" required>Display name</Label>
                  <Input
                    id="display-name"
                    value={name}
                    invalid={!name.trim()}
                    aria-describedby="display-name-hint"
                    onChange={(e) => {
                      setName(e.target.value);
                      setSaved(false);
                    }}
                  />
                  <p id="display-name-hint" className="text-xs text-muted-foreground">
                    {name.trim() ? "Use your full name." : "Display name is required."}
                  </p>
                </div>
                <div className="space-y-1.5">
                  <Label htmlFor="timezone">Time zone</Label>
                  <Select id="timezone" defaultValue="utc">
                    <option value="utc">UTC</option>
                    <option value="est">Eastern Time</option>
                    <option value="ist">India Standard Time</option>
                  </Select>
                </div>
                <div className="flex justify-end">
                  <Button type="submit" disabled={!name.trim()}>Save changes</Button>
                </div>
              </CardContent>
            </form>
          </CardContainer>
        </TabsContent>

        <TabsContent value="notifications" className="pt-4">
          <CardContainer>
            <CardContent className="divide-y divide-border py-0">
              <SettingRow id="digest" title="Weekly digest" description="A summary of project progress every Monday.">
                <Switch
                  checked={digest}
                  onCheckedChange={setDigest}
                  aria-labelledby="digest-label"
                  aria-describedby="digest-desc"
                />
              </SettingRow>
              <SettingRow id="mentions" title="Mentions" description="Email me when someone mentions me.">
                <Switch defaultChecked aria-labelledby="mentions-label" aria-describedby="mentions-desc" />
              </SettingRow>
            </CardContent>
          </CardContainer>
        </TabsContent>
      </Tabs>
    </div>
  );
}
